mapper.select:
SELECT n.*, u.username, u.avatar, (SELECT COUNT(*) FROM note_like WHERE note_id = n.id) as like_count, (SELECT COUNT(*) FROM note_collect WHERE note_id = n.id) as collect_count, (SELECT COUNT(*) FROM comment WHERE note_id = n.id) as comment_count FROM note n LEFT JOIN user u ON n.user_id = u.id
AND n.category = #{category}
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY n.created_at DESC, n.id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE note
title = #{title}, content = #{content}, images = #{images}, category = #{category},
WHERE id = #{id}
